import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry sdpa_kernel(
    .param .u64 Q_ptr,
    .param .u64 K_ptr,
    .param .u64 V_ptr,
    .param .u64 Out_ptr
)
    .maxnreg 40
{
    .reg .u32 %r<200>;
    .reg .u64 %rd<60>;
    .reg .f32 %f<200>;
    .reg .b16 %h<60>;
    .reg .pred %p<40>;

    .shared .align 16 .b8 Qs[2048];
    .shared .align 4 .b8 Sc[1024];
    .shared .align 4 .b8 Ex[1024];
    .shared .align 4 .b8 Rd[1024];

    ld.param.u64 %rd1, [Q_ptr];
    ld.param.u64 %rd2, [K_ptr];
    ld.param.u64 %rd3, [V_ptr];
    ld.param.u64 %rd4, [Out_ptr];

    mov.u32 %r1, %ctaid.x;      // idx : 0..16383 (B*H*S)
    mov.u32 %r2, %tid.x;        // tid : 0..255

    // bounds check: idx < 16384
    setp.ge.u32 %p1, %r1, 16384;
    @%p1 bra DONE_ALL;

    shr.u32 %r3, %r1, 8;        // bh = idx >> 8  (b*32+h)
    shl.b32 %r5, %r3, 8;        // bhS = bh << 8
    shl.b32 %r6, %r1, 11;       // byteOffQ = idx * 2048 (row byte offset, Q/Out share layout)

    cvt.u64.u32 %rd5, %r6;
    add.s64 %rd6, %rd1, %rd5;   // Qaddr = Qptr + byteOffQ (row base, global)

    mov.u32 %r10, Qs;
    mov.u32 %r11, Sc;
    mov.u32 %r12, Ex;
    mov.u32 %r13, Rd;

    shl.b32 %r43, %r2, 2;       // toff = tid*4
    add.u32 %r46, %r11, %r43;   // ScAddr (shared) for this thread
    add.u32 %r47, %r12, %r43;   // ExAddr (shared) for this thread
    add.u32 %r48, %r13, %r43;   // RdAddr (shared) for this thread

    // ---------------- Load Q row into shared memory (vectorized, coalesced) ----------------
    shl.b32 %r50, %r2, 3;        // byte offset = tid*8 (contiguous 8B chunk per thread)
    cvt.u64.u32 %rd10, %r50;
    add.s64 %rd11, %rd6, %rd10;
    ld.global.v2.u32 {%r100, %r101}, [%rd11];
    add.u32 %r52, %r10, %r50;
    st.shared.v2.u32 [%r52], {%r100, %r101};
    bar.sync 0;

    // ---------------- Compute score for key j = tid ----------------
    add.u32 %r14, %r5, %r2;      // rowIndexK = bhS + tid
    shl.b32 %r15, %r14, 11;      // byteOffK
    cvt.u64.u32 %rd20, %r15;
    add.s64 %rd21, %rd2, %rd20;  // Kaddr row base

    mov.f32 %f1, 0f00000000;
    mov.f32 %f170, 0f00000000;
    mov.u32 %r16, 0;
SCORE_LOOP:
    setp.ge.u32 %p2, %r16, 1024;
    @%p2 bra SCORE_DONE;
    shl.b32 %r17, %r16, 1;
    add.u32 %r18, %r10, %r17;
    ld.shared.v4.u32 {%r90, %r91, %r92, %r93}, [%r18];
    cvt.u64.u32 %rd22, %r17;
    add.s64 %rd23, %rd21, %rd22;
    ld.global.nc.v4.u32 {%r94, %r95, %r96, %r97}, [%rd23];
    mov.b32 {%h5, %h6}, %r90;
    mov.b32 {%h7, %h8}, %r91;
    mov.b32 {%h9, %h10}, %r92;
    mov.b32 {%h11, %h16}, %r93;
    mov.b32 {%h12, %h13}, %r94;
    mov.b32 {%h14, %h15}, %r95;
    mov.b32 {%h17, %h18}, %r96;
    mov.b32 {%h19, %h20}, %r97;
    cvt.f32.f16 %f2, %h5;
    cvt.f32.f16 %f3, %h12;
    fma.rn.f32 %f1, %f2, %f3, %f1;
    cvt.f32.f16 %f4, %h6;
    cvt.f32.f16 %f5, %h13;
    fma.rn.f32 %f170, %f4, %f5, %f170;
    cvt.f32.f16 %f6, %h7;
    cvt.f32.f16 %f7, %h14;
    fma.rn.f32 %f1, %f6, %f7, %f1;
    cvt.f32.f16 %f8, %h8;
    cvt.f32.f16 %f9, %h15;
    fma.rn.f32 %f170, %f8, %f9, %f170;
    cvt.f32.f16 %f2, %h9;
    cvt.f32.f16 %f3, %h17;
    fma.rn.f32 %f1, %f2, %f3, %f1;
    cvt.f32.f16 %f4, %h10;
    cvt.f32.f16 %f5, %h18;
    fma.rn.f32 %f170, %f4, %f5, %f170;
    cvt.f32.f16 %f6, %h11;
    cvt.f32.f16 %f7, %h19;
    fma.rn.f32 %f1, %f6, %f7, %f1;
    cvt.f32.f16 %f8, %h16;
    cvt.f32.f16 %f9, %h20;
    fma.rn.f32 %f170, %f8, %f9, %f170;
    add.u32 %r16, %r16, 8;
    bra SCORE_LOOP;
