_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("sdpa_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        assert Q.shape == K.shape == V.shape
        B, H, S, D = Q.shape
        assert B == 2 and H == 32 and S == 256 and D == 1024
        assert Q.dtype == torch.float16 and Q.is_cuda

        Q = Q.contiguous()
        K = K.contiguous()
        V = V.contiguous()
        out = torch.empty_like(Q)

        module = _get_ptx_module()

        total_blocks = B * H * S  # 16384
        module.launch(
            "sdpa_kernel",
            grid=(total_blocks, 1, 1),
            block=(256, 1, 1),
            arguments=[Q, K, V, out],
            shared_memory=0,
            stream=torch.cuda.current_stream(Q.device),
        )

        return out
